import { expect } from 'chai';
import fs from 'node:fs';
import StyleDictionary from 'style-dictionary';

const ROOT = 'bpo';

const rmRoot = () => {
  fs.rmSync(ROOT, { recursive: true, force: true });
};

const makeDictionary = (buildPath, destination) =>
  new StyleDictionary({
    tokens: { foo: { $value: 'bar' } },
    hooks: {
      formats: {
        txt: () => 'FILE_CONTENT',
      },
    },
    platforms: {
      web: {
        buildPath,
        files: [{ destination, format: 'txt' }],
      },
    },
  });

async function capture(fn) {
  const lines = [];
  const originalLog = console.log;
  console.log = (...args) => {
    lines.push(args.map((arg) => (typeof arg === 'string' ? arg : String(arg))).join(' '));
  };
  let result;
  let error = null;
  try {
    result = await fn();
  } catch (err) {
    error = err;
  } finally {
    console.log = originalLog;
  }
  return { result, error, lines };
}

async function buildRun(cfg, expected) {
  rmRoot();
  const sd = makeDictionary(cfg.buildPath, cfg.destination);
  const buildCap = await capture(() => sd.buildPlatform('web'));
  const formatCap = await capture(() => sd.formatPlatform('web'));
  const error = buildCap.error || formatCap.error;
  const formatted = (formatCap.result || [])[0] || {};
  return {
    error,
    destination: formatted.destination,
    logs: [...buildCap.lines, ...formatCap.lines],
    file: fs.existsSync(expected) ? fs.readFileSync(expected, 'utf8') : null,
  };
}

describe('build: Windows-separator and POSIX buildPath configs are equivalent', () => {
  after(() => rmRoot());

  const pairs = [
    {
      name: 'buildPath ending in a backslash builds the same path as one ending in a slash',
      ref: { buildPath: 'bpo/', destination: 'file.txt' },
      alt: { buildPath: 'bpo\\', destination: 'file.txt' },
      expected: 'bpo/file.txt',
    },
    {
      name: 'multi-segment backslash buildPath builds the same path as its slash equivalent',
      ref: { buildPath: 'bpo/sub1/sub2/', destination: 'file.txt' },
      alt: { buildPath: 'bpo\\sub1\\sub2\\', destination: 'file.txt' },
      expected: 'bpo/sub1/sub2/file.txt',
    },
    {
      name: 'backslash buildPath with backslash destination builds the same path as an all-slash config',
      ref: { buildPath: 'bpo/', destination: 'nested/file.txt' },
      alt: { buildPath: 'bpo\\', destination: 'nested\\file.txt' },
      expected: 'bpo/nested/file.txt',
    },
    {
      name: 'backslash destination alone builds the same path as a slash destination',
      ref: { buildPath: 'bpo/', destination: 'nested/file.txt' },
      alt: { buildPath: 'bpo/', destination: 'nested\\file.txt' },
      expected: 'bpo/nested/file.txt',
    },
  ];

  pairs.forEach((pair) => {
    it(pair.name, async function () {
      this.timeout(30000);
      const refRun = await buildRun(pair.ref, pair.expected);
      const altRun = await buildRun(pair.alt, pair.expected);
      const where = JSON.stringify({ ref: pair.ref, alt: pair.alt });

      expect(refRun.error, `reference build must not throw (${where})`).to.be.null;
      expect(altRun.error, `variant build must not throw (${where})`).to.be.null;

      // the reference (all-slash) config reports the canonical path
      expect(refRun.destination, `reference reports ${pair.expected}`).to.equal(pair.expected);
      // the equivalent config reports the identical path, with no doubled or stray separators
      expect(
        altRun.destination,
        `variant must report the same path as the reference (${where})`,
      ).to.equal(refRun.destination);
      expect(altRun.destination, `variant must report exactly ${pair.expected}`).to.equal(
        pair.expected,
      );
      expect(altRun.destination, `no backslashes in reported path (${where})`).to.not.include('\\');
      expect(altRun.destination, `no doubled separators in reported path (${where})`).to.not.match(
        /\/\//,
      );

      // the file is actually written at that path
      expect(refRun.file, `reference file written at ${pair.expected}`).to.equal('FILE_CONTENT');
      expect(altRun.file, `variant file written at ${pair.expected}`).to.equal('FILE_CONTENT');

      // the user-visible build output is identical between equivalent configs
      expect(altRun.logs, `build logs must match the reference config (${where})`).to.deep.equal(
        refRun.logs,
      );
      for (const line of [...refRun.logs, ...altRun.logs]) {
        expect(line, `no doubled separators in reported path: ${line}`).to.not.match(/\/\//);
        expect(line, `no backslashes in reported path: ${line}`).to.not.include('\\');
      }
    });
  });
});

