describe('build: buildPath behaves the same with and without a trailing separator', () => {
  after(() => rmRoot());

  const pairs = [
    {
      name: 'POSIX buildPath without a trailing separator matches one with a trailing separator',
      ref: { buildPath: 'bpt/s/', destination: 'f.txt' },
      alt: { buildPath: 'bpt/s', destination: 'f.txt' },
      expected: 'bpt/s/f.txt',
    },
    {
      name: 'backslash buildPath without a trailing separator matches one with a trailing separator',
      ref: { buildPath: 'bpt\\s\\', destination: 'f.txt' },
      alt: { buildPath: 'bpt\\s', destination: 'f.txt' },
      expected: 'bpt/s/f.txt',
    },
  ];

  pairs.forEach((pair) => {
    it(pair.name, async function () {
      this.timeout(30000);
      const refRun = await buildRun(pair.ref, pair.expected);
      const altRun = await buildRun(pair.alt, pair.expected);
      const where = JSON.stringify({ ref: pair.ref, alt: pair.alt });

      expect(refRun.error, `trailing-separator build must not throw (${where})`).to.be.null;
      expect(altRun.error, `no-trailing-separator build must not throw (${where})`).to.be.null;

      // both variants report exactly the same canonical path
      expect(
        refRun.destination,
        `trailing variant must report ${pair.expected} (${where})`,
      ).to.equal(pair.expected);
      expect(
        altRun.destination,
        `no-trailing variant must report the same path as the trailing variant (${where})`,
      ).to.equal(refRun.destination);
      expect(altRun.destination, `no backslashes in reported path (${where})`).to.not.include('\\');
      expect(altRun.destination, `no doubled separators in reported path (${where})`).to.not.match(
        /\/\//,
      );

      // both variants write the file at that same path
      expect(refRun.file, `trailing variant file at ${pair.expected}`).to.equal('FILE_CONTENT');
      expect(altRun.file, `no-trailing variant file at ${pair.expected}`).to.equal('FILE_CONTENT');

      // user-visible build output is identical between the two variants
      expect(
        altRun.logs,
        `build logs must match the trailing-separator config (${where})`,
      ).to.deep.equal(refRun.logs);
      for (const line of [...refRun.logs, ...altRun.logs]) {
        expect(line, `no doubled separators in reported path: ${line}`).to.not.match(/\/\//);
        expect(line, `no backslashes in reported path: ${line}`).to.not.include('\\');
      }
    });
  });
});

