// Builds the platform, then cleans it twice (the second clean targets an
// already-clean state), recording filesystem state and everything reported.
async function buildAndClean(cfg, expected) {
  rmRoot();
  const sd = makeDictionary(cfg.buildPath, cfg.destination);

  const buildCap = await capture(() => sd.buildPlatform('web'));
  const existsAfterBuild = fs.existsSync(expected);

  const cleanCap = await capture(() => sd.cleanPlatform('web'));
  const existsAfterClean = fs.existsSync(expected);
  const rootAfterClean = fs.existsSync(ROOT);

  const cleanAgainCap = await capture(() => sd.cleanPlatform('web'));

  const error = buildCap.error || cleanCap.error || cleanAgainCap.error;
  return {
    error,
    existsAfterBuild,
    existsAfterClean,
    rootAfterClean,
    logs: [...buildCap.lines, ...cleanCap.lines, ...cleanAgainCap.lines],
  };
}

describe('clean: Windows-separator and POSIX configs clean the same paths and prune the same directories', () => {
  after(() => rmRoot());

  const pairs = [
    {
      name: 'buildPath ending in a backslash cleans the same path as one ending in a slash',
      ref: { buildPath: 'bpc/', destination: 'file.txt' },
      alt: { buildPath: 'bpc\\', destination: 'file.txt' },
      expected: 'bpc/file.txt',
    },
    {
      name: 'multi-segment backslash buildPath cleans and prunes like its slash equivalent',
      ref: { buildPath: 'bpc/sub1/sub2/', destination: 'file.txt' },
      alt: { buildPath: 'bpc\\sub1\\sub2\\', destination: 'file.txt' },
      expected: 'bpc/sub1/sub2/file.txt',
    },
    {
      name: 'backslash buildPath with backslash destination cleans like an all-slash config',
      ref: { buildPath: 'bpc/', destination: 'nested/file.txt' },
      alt: { buildPath: 'bpc\\', destination: 'nested\\file.txt' },
      expected: 'bpc/nested/file.txt',
    },
    {
      name: 'POSIX buildPath cleans the same with and without a trailing separator',
      ref: { buildPath: 'bpc/s/', destination: 'f.txt' },
      alt: { buildPath: 'bpc/s', destination: 'f.txt' },
      expected: 'bpc/s/f.txt',
    },
    {
      name: 'backslash buildPath cleans the same with and without a trailing separator',
      ref: { buildPath: 'bpc\\s\\', destination: 'f.txt' },
      alt: { buildPath: 'bpc\\s', destination: 'f.txt' },
      expected: 'bpc/s/f.txt',
    },
    {
      name: 'backslash destination alone cleans like a slash destination',
      ref: { buildPath: 'bpc/', destination: 'nested/file.txt' },
      alt: { buildPath: 'bpc/', destination: 'nested\\file.txt' },
      expected: 'bpc/nested/file.txt',
    },
  ];

  pairs.forEach((pair) => {
    it(pair.name, async function () {
      this.timeout(30000);
      const refRun = await buildAndClean(pair.ref, pair.expected);
      const altRun = await buildAndClean(pair.alt, pair.expected);
      const where = JSON.stringify({ ref: pair.ref, alt: pair.alt });

      expect(refRun.error, `reference build+clean must not throw (${where})`).to.be.null;
      expect(altRun.error, `variant build+clean must not throw (${where})`).to.be.null;

      for (const [who, run] of [
        ['reference', refRun],
        ['variant', altRun],
      ]) {
        expect(run.existsAfterBuild, `${who} built the file at ${pair.expected}`).to.be.true;
        expect(run.existsAfterClean, `${who} removed the built file after clean`).to.be.false;
        expect(run.rootAfterClean, `${who} pruned the emptied output directories after clean`).to.be
          .false;
      }

      // cleaning reports exactly the same paths for equivalent configs,
      // with no doubled or stray separators anywhere in the output
      expect(altRun.logs, `clean logs must match the reference config (${where})`).to.deep.equal(
        refRun.logs,
      );
      for (const line of [...refRun.logs, ...altRun.logs]) {
        expect(line, `no doubled separators in reported path: ${line}`).to.not.match(/\/\//);
        expect(line, `no backslashes in reported path: ${line}`).to.not.include('\\');
      }
    });
  });
});

