const variants = [
  { buildPath: 'bpe/', destination: 'file.txt', expected: 'bpe/file.txt' },
  { buildPath: 'bpe', destination: 'file.txt', expected: 'bpe/file.txt' },
  { buildPath: 'bpe\\', destination: 'file.txt', expected: 'bpe/file.txt' },
  { buildPath: 'bpe\\s\\', destination: 'file.txt', expected: 'bpe/s/file.txt' },
  { buildPath: 'bpe\\s', destination: 'file.txt', expected: 'bpe/s/file.txt' },
  { buildPath: 'bpe\\', destination: 'nested\\file.txt', expected: 'bpe/nested/file.txt' },
  { buildPath: 'bpe', destination: 'nested\\file.txt', expected: 'bpe/nested/file.txt' },
  { buildPath: 'bpe/', destination: 'nested/file.txt', expected: 'bpe/nested/file.txt' },
];

describe('neither building nor cleaning errors for backslash separators or a missing trailing separator', () => {
  after(() => rmRoot());

  variants.forEach((variant) => {
    const label = `buildPath=${JSON.stringify(variant.buildPath)} destination=${JSON.stringify(
      variant.destination,
    )}`;

    it(`no error for ${label}`, async function () {
      this.timeout(30000);
      rmRoot();

      const sd = makeDictionary(variant.buildPath, variant.destination);

      // building must not raise
      const buildCap = await capture(() => sd.buildPlatform('web'));
      expect(buildCap.error, `build must not throw for ${label}`).to.be.null;
      expect(
        fs.existsSync(variant.expected),
        `file must be written at ${variant.expected} for ${label}`,
      ).to.be.true;
      expect(fs.readFileSync(variant.expected, 'utf8')).to.equal('FILE_CONTENT');

      // cleaning must not raise and must remove the built file
      const cleanCap = await capture(() => sd.cleanPlatform('web'));
      expect(cleanCap.error, `clean must not throw for ${label}`).to.be.null;
      expect(fs.existsSync(variant.expected), `file must be removed after clean for ${label}`).to.be
        .false;

      // cleaning an already-clean platform must not raise
      const cleanAgainCap = await capture(() => sd.cleanPlatform('web'));
      expect(cleanAgainCap.error, `second clean must not throw for ${label}`).to.be.null;

      // cleaning a platform that was never built must not raise either
      const fresh = makeDictionary(variant.buildPath, variant.destination);
      const formatCap = await capture(() => fresh.formatPlatform('web'));
      expect(formatCap.error, `format must not throw for ${label}`).to.be.null;
      const cleanNeverBuilt = await capture(() => fresh.cleanPlatform('web'));
      expect(cleanNeverBuilt.error, `clean without prior build must not throw for ${label}`).to.be
        .null;
    });
  });
});
